import{_ as e,o as a,c as t,ac as _}from"./chunks/framework.B-3EzaJq.js";const h=JSON.parse('{"title":"中国共产党第十二届中央委员会委员、候补委员名单","description":"","frontmatter":{"prev":{"text":"[报道]胡乔木同志就党章修改问题答新华社记者问","link":"./胡乔木同志就党章修改问题答新华社记者问"},"next":{"text":"中国共产党第十二次全国代表大会主席团名单","link":"./中国共产党第十二次全国代表大会主席团名单"}},"headers":[],"relativePath":"12/中国共产党第十二届中央委员会委员、候补委员名单.md","filePath":"12/中国共产党第十二届中央委员会委员、候补委员名单.md"}'),r={name:"12/中国共产党第十二届中央委员会委员、候补委员名单.md"};function n(i,p,l,o,s,c){return a(),t("div",null,[...p[0]||(p[0]=[_('<h1 id="中国共产党第十二届中央委员会委员、候补委员名单" tabindex="-1">中国共产党第十二届中央委员会委员、候补委员名单 <a class="header-anchor" href="#中国共产党第十二届中央委员会委员、候补委员名单" aria-label="Permalink to &quot;中国共产党第十二届中央委员会委员、候补委员名单&quot;">​</a></h1><nav class="table-of-contents"><ul><li><a href="#中央委员">中央委员</a></li><li><a href="#中央候补委员">中央候补委员</a></li></ul></nav><div class="text-center"><h2 id="中央委员" tabindex="-1">中央委员 <a class="header-anchor" href="#中央委员" aria-label="Permalink to &quot;中央委员&quot;">​</a></h2></div><p><em>（共二百一十人）</em></p><p>  （按姓氏笔划为序）</p><p>  于明涛 于洪恩 万 达 万 里 万海峰</p><p>  马文瑞 马兴元 习仲勋 王 芳 王 猛</p><p>  王 震 王丙乾 王汉斌 王光中 王光宇</p><p>  王兆国 王全国 王任重 王克文 王诚汉</p><p>  王恩茂 王崇伦 王朝文（苗族） 王鹤寿</p><p>  韦国清（壮族） 尤太忠 毛致用</p><p>  乌兰夫（蒙古族） 方 毅 巴 桑（女，藏族）</p><p>  邓力群 邓小平 邓颖超（女） 邓稼先</p><p>  布 赫（蒙古族） 叶 飞 叶剑英 田纪云</p><p>  白栋材 司马义·艾买提（维吾尔族） 邢燕子（女）</p><p>  吕培俭 朱云谦 朱光亚 朱穆之 乔 石</p><p>  乔晓光 伍精华（彝族） 任仲夷 华国锋</p><p>  向守志 刘 震 刘正威 刘华清 刘志坚</p><p>  刘复之 刘振华 江泽民 江拥辉 池必卿</p><p>  安平生 许家屯 孙大光 阴法唐 严东生</p><p>  苏 钢 苏毅然 李 锐 李 鹏 李力安</p><p>  李子奇 李立功 李东冶 李先念 李启明</p><p>  李学智 李梦华 李绪鄂 李森茂 李瑞环</p><p>  李锡铭 李溪薄 李德生 李耀文 杨 波</p><p>  杨 勇 杨 堤 杨成武 杨汝岱 杨易辰</p><p>  杨尚昆 杨得志 杨静仁（回族） 杨德中</p><p>  肖 华 肖 寒 肖全夫 吴全清 吴学谦</p><p>  何 康 何东昌 余秋里 谷 牧 沈 图</p><p>  沈因洛 宋 平 宋任穷 张 寿 张 震</p><p>  张廷发 张再旺 张劲夫 张爱萍 张锽秀</p><p>  张曙光 陈 云 陈 彬 陈 雷 陈仁洪</p><p>  陈丕显 陈伟达 陈希同 陈国栋 陈福汉</p><p>  陈慕华（女） 陈璞如 林 若 林乎加</p><p>  林丽韫（女） 罗青长 周 惠 周子健</p><p>  周世忠 周建南 郑三生 郑拓彬 项 南</p><p>  赵守一 赵兴元 赵志坚 赵苍璧 赵南起（朝鲜族）</p><p>  赵海峰 赵紫阳 郝建秀（女） 胡 宏</p><p>  胡 绳 胡立教 胡乔木 胡启立 胡耀邦</p><p>  柳 林 饶兴礼 洪学智 姚 广 姚依林</p><p>  贺进恒 贺敬之 秦 川 秦仲达 秦基伟</p><p>  袁宝华 聂荣臻 莫文祥 热 地（藏族）</p><p>  顾秀莲（女） 钱正英（女） 钱永昌 铁 瑛</p><p>  铁木尔·达瓦买提（维吾尔族） 倪志福 徐少甫</p><p>  徐向前 殷 渊 高扬文 郭力文（女） 唐 克</p><p>  黄 华 黄知真 黄新廷 崔乃夫 崔月犁</p><p>  康世恩 康克清（女） 章 泽 梁必业</p><p>  梁灵光 梁步庭 彭 冲 彭 真 蒋南翔</p><p>  韩先楚 韩培信 覃应机（壮族） 傅奎清</p><p>  焦林义 鲁大东 谢希德（女） 谢振华</p><p>  强晓初 解 峰 廖汉生 廖承志</p><p>  赛福鼎（维吾尔族） 谭友林 谭启龙 谭善和</p><p>  薛 驹 穆 青（回族） 戴苏理</p><hr><div class="text-center"><h2 id="中央候补委员" tabindex="-1">中央候补委员 <a class="header-anchor" href="#中央候补委员" aria-label="Permalink to &quot;中央候补委员&quot;">​</a></h2></div><p><em>（共一百三十八人）</em></p><p>  （以得票多少为序）</p><p>  杨泰芳 郎大忠（傣族） 尉健行 蒋民宽</p><p>  尹长民（女） 罗尚才（布依族） 周光召</p><p>  郑光迪（女） 姜燮生 彭士禄</p><p>  尹 俊（白族） 年得祥（回族） 李 刚</p><p>  陈素芝（女，满族） 胡 平 胡锦涛 袁芳烈</p><p>  格桑多杰（藏族） 蒋心雄 杨析综</p><p>  金宝生（瑶族） 赵 宗 唐仲文 潘荣文（女）</p><p>  朱 训 刘树生（回族） 李 冰（女）</p><p>  吴文英（女） 张序登 陆懋曾 陈 焕</p><p>  林殷才 梁栋材 熊清泉 魏鸣一 于振武</p><p>  于鸿礼 卢良恕 朱厚泽 乔学亭 邹竞蒙</p><p>  张辛泰 宫本言 黎 明 王 群 李慧芬（女）</p><p>  杨岭多吉（藏族） 周阿庆 黄德懋 刘贵谦</p><p>  孙维本 栗寿山 钱其琛 董继昌</p><p>  马思忠（回族） 王越丰（黎族）</p><p>  巴图巴根（蒙古族） 卢功勋 田世兴</p><p>  刘鸿儒 张万年 梁成业（壮族） 王忍之</p><p>  王林鹤 刘玉洁（女） 刘国光 许 勤</p><p>  贾那布尔（哈萨克族） 黑伯理（回族）</p><p>  丁凤英（女） 韩 叙 谢 非 魏金山</p><p>  孙国治 李铁映 李淑铮（女） 吴祖强</p><p>  何光远 张 祥 聂奎聚 高德占 黄 枢</p><p>  马忠臣 王学珍 邢崇智 刘友法 刘明辉</p><p>  汪家镒（女） 张伯祥 韩瑞阶 邢至康（女）</p><p>  刘 毅 董占林 王建功 张万欣 安志文</p><p>  李 锋 吴蔚然 何竹康 陈作霖 宋 健</p><p>  林涧青 邹家华 罗 干 马卫华 李化民</p><p>  黄甘英（女） 赵东宛 吴向必（苗族）</p><p>  高厚良 杨正午（土家族） 严 政 刘维明</p><p>  钱学森 杨海波 马 洪 房维中 王 蒙</p><p>  李际均 徐 信 高占祥 叶选平 刘海清</p><p>  马 明 王六生 李昌安 张健民 任 荣</p><p>  杨永良 王扶之 张根生 吴冷西 袁 俊</p><p>  王金山 李瑞山 王 谦 于 桑 汪东兴</p>',90)])])}const m=e(r,[["render",n]]);export{h as __pageData,m as default};
